رة الموديل","alt_en":"xBloom Studio · model photo"},{"url":"https://cdn.shopify.com/s/files/1/0611/5704/8544/files/xbloom_Studio_Midnight_Black_01.webp?v=1777343051","source_url":"https://xbloom.com/products/xbloom-studio","usage_status":"source_linked","alt_ar":"xBloom Studio · صورة الموديل","alt_en":"xBloom Studio · model photo"},{"url":"https://cdn.shopify.com/s/files/1/0611/5704/8544/files/xbloom_Studio_Midnight_Black_03.webp?v=1777343271","source_url":"https://xbloom.com/products/xbloom-studio","usage_status":"source_linked","alt_ar":"xBloom Studio · صورة الموديل","alt_en":"xBloom Studio · model photo"},{"url":"https://cdn.shopify.com/s/files/1/0611/5704/8544/files/xbloom_Studio_Midnight_Black_04.webp?v=1777343271","source_url":"https://xbloom.com/products/xbloom-studio","usage_status":"source_linked","alt_ar":"xBloom Studio · صورة الموديل","alt_en":"xBloom Studio · model photo"}]}]$equipment_galleries$::jsonb)
    AS p(id uuid, name text, images jsonb)
), updated AS (
  UPDATE public.equipment_models e
  SET specifications = jsonb_set(e.specifications, '{catalog}',
    (e.specifications->'catalog') || jsonb_build_object(
      'images', p.images, 'gallery_verified_at', '2026-10-09'), true)
  FROM payload p
  WHERE e.id = p.id AND e.name = p.name AND NOT e.requires_review
    AND e.specifications->'catalog'->>'schema_version' = '1'
  RETURNING e.id
)
SELECT count(*) AS updated_models FROM updated;
